export function groundStone(
	inscription: Inscription,
	facts: string[],
	paragraph: string
): string | null {
	const allowed = new Set([...nameTokens(inscription), ...MONTHS]);
	const body = keptSentences(paragraph, facts.map(norm), allowed).join(' ');
