// Usage: node benchmarks/record-stories.ts <base-url>
// Freezes story inputs for the evals: researches each reviewed fixture's people through the running
// app and saves every candidate with the text of its sources to fixtures/stories.json.
// Needs the app running with real keys (`pnpm build && pnpm preview --port 5400`).
// Labels start unreviewed: `match` is null until the user sets the index of the candidate who is
// the person on the stone, or -1 when none is.
import { readFile, writeFile } from 'node:fs/promises';
import { normalizeInscriptions } from '../src/lib/server/inscription.ts';
import { fetchPage } from '../src/lib/server/pages.ts';
import type { Candidate, Inscription } from '../src/lib/types.ts';

interface Fixture {
	file: string;
	people: { name: string; born: string | null; died: string | null }[];
	reviewed: boolean;
}

interface StoryCase {
	file: string;
	inscription: Inscription;
	candidates: Candidate[];
	pages: Record<string, string | null>;
	match: number | null;
	reviewed: false;
}

const [base] = process.argv.slice(2);
const outFile = new URL('../fixtures/stories.json', import.meta.url);
const manifest: Fixture[] = JSON.parse(
	await readFile(new URL('../fixtures/manifest.json', import.meta.url), 'utf8')
);

/**
 * Researches one person through the running app.
 * @param inscription The stone's person.
 * @returns Candidates, best first.
 * @throws {Error} On a non-2xx response.
 */
async function research(inscription: Inscription): Promise<Candidate[]> {
	const res = await fetch(new URL('/api/research', base), {
		method: 'POST',
		headers: { 'content-type': 'application/json', origin: new URL(base).origin },
		body: JSON.stringify(inscription),
		signal: AbortSignal.timeout(300_000)
	});
	const body = (await res.json()) as { candidates: Candidate[] };
	if (!res.ok) throw new Error(`research ${res.status} ${JSON.stringify(body).slice(0, 160)}`);
	return body.candidates;
}

const cases: StoryCase[] = [];
for (const f of manifest.filter((m) => m.reviewed)) {
	for (const inscription of normalizeInscriptions(f.people.map((p) => ({ ...p, voice: null })))) {
		const candidates = await research(inscription);
		const urls = [...new Set(candidates.flatMap((c) => c.sources.map((s) => s.url)))];
		const pages = Object.fromEntries(
			await Promise.all(urls.map(async (u) => [u, await fetchPage(u)] as const))
		);
		cases.push({ file: f.file, inscription, candidates, pages, match: null, reviewed: false });
		console.error(`${inscription.name.padEnd(32)} ${candidates.length} candidates, ${urls.length} pages`);
	}
}
await writeFile(outFile, `${JSON.stringify(cases, null, '\t')}\n`);

