import { createScorer } from '@mastra/core/evals';
import { z } from 'zod';

const JUDGE_MODEL = 'google/gemini-3.8-flash';

/** What the story was written from: the person's name and every true text about them. */
export interface LifeClaimsInput {
	subject: string;
	context: string[];
}

const claimSchema = z.object({
	claim: z.string().describe('One claim, restated in plain words.'),
	kind: z.enum(['life', 'atmosphere']),
	evidence: z
		.string()
		.nullable()
		.describe('Exact words copied from the records that support the claim; null when none do.')
});

export type Claim = z.infer<typeof claimSchema>;

const JUDGE_INSTRUCTIONS = `<role>You audit a ghost story told at a grave for claims about a real person's life that the records do not support.</role>

<how_you_work>
- Split the story into every claim it makes, one per item. A sentence can hold several.
- kind "life": anything about the real person while alive: names, dates, ages, places, family, relationships, work, events, possessions, habits, traits, memories, and feelings about any of those.
- kind "atmosphere": the openly fictional frame: being a ghost, the grave, the dark, the weather, the visitor, the present moment, the afterlife.
- A claim that dresses a life detail in otherworld words is "life". "From beyond I watched my children grow" claims children.
- evidence: copy the exact words from the records that state the claim. Copy, do not paraphrase.
</how_you_work>

<never>
- Never mark a claim "atmosphere" because it is poetic. When unsure, it is "life".
- Never give evidence that only makes a claim plausible. It must state the claim.
</never>`;

/**
 * Lowercases and collapses everything except letters and digits to single spaces.
 * @param s Text to normalize.
 * @returns Normalized text.
 */
function norm(s: string): string {
	return s
		.toLowerCase()
		.replace(/[^\p{L}\p{N}]+/gu, ' ')
		.trim();
}

/**
 * Finds life claims whose evidence is missing or not found word for word in the records. The judge
 * names the evidence; this check keeps it from vouching for words the records do not contain.
 * @param claims Claims the judge extracted.
 * @param context Records the story may draw on.
 * @returns Life claims and the subset that failed.
 */
export function auditClaims(
	claims: Claim[],
	context: string[]
): { life: Claim[]; unsupported: Claim[] } {
	const records = ` ${context.map(norm).join(' | ')} `;
	const life = claims.filter((c) => c.kind === 'life');
	const unsupported = life.filter((c) => {
		const evidence = norm(c.evidence ?? '');
		return !evidence || !records.includes(` ${evidence} `);
	});
	return { life, unsupported };
}

/**
 * Builds the scorer for life claims in a told story.
 * @param apiKey Gemini API key for the judge.
 * @returns A scorer: the share of life claims backed by the records, 1 when the story makes none.
 */
export function lifeClaimsScorer(apiKey: string) {
	return createScorer<LifeClaimsInput, string>({
		id: 'life-claims',
		description: 'Every claim about the life of the person must be stated in the records.',
		judge: {
			model: { id: JUDGE_MODEL, apiKey },
			instructions: JUDGE_INSTRUCTIONS,
			modelSettings: { temperature: 0 }
		}
	})
		.analyze({
			description: 'Extract claims and the record text that supports each',
			outputSchema: z.object({ claims: z.array(claimSchema) }),
			createPrompt: ({ run }) =>
				`<records>\n${run.input!.context.join('\n---\n')}\n</records>\n\n<story subject="${run.input!.subject}">\n${run.output}\n</story>\n\nBased on the records above, list every claim the story makes.`
		})
		.generateScore(({ run, results }) => {
			const { life, unsupported } = auditClaims(results.analyzeStepResult.claims, run.input!.context);
			return life.length ? (life.length - unsupported.length) / life.length : 1;
		})
		.generateReason(({ run, results }) =>
			auditClaims(results.analyzeStepResult.claims, run.input!.context)
				.unsupported.map((c) => `unsupported: ${c.claim} (evidence: ${c.evidence ?? 'none'})`)
				.join('\n')
		);
}

import { describe, expect, it } from 'vitest';
import { auditClaims, type Claim } from './life-claims';

const context = [
	'Gaynor Hawks taught piano at Lincoln Elementary for forty years.',
	'My name was Gaynor Claire Hawks. I died September 3, 2017.'
];

/**
 * Builds a life claim.
 * @param evidence Quoted record text, or null.
 * @returns The claim.
 */
const life = (evidence: string | null): Claim => ({ claim: 'taught piano', kind: 'life', evidence });

describe('auditClaims', () => {
	it('accepts a life claim whose evidence appears in the records', () => {
		expect(auditClaims([life('taught piano at Lincoln Elementary')], context).unsupported).toEqual([]);
	});

	it('ignores case, punctuation and quote style in the evidence', () => {
		expect(auditClaims([life('“TAUGHT piano,  at Lincoln”')], context).unsupported).toEqual([]);
	});

	it('rejects a life claim with no evidence', () => {
		const claim = life(null);
		expect(auditClaims([claim], context).unsupported).toEqual([claim]);
	});

	it('rejects evidence the records do not contain, even when it sounds right', () => {
		const claim = life('taught piano for fifty years');
		expect(auditClaims([claim], context).unsupported).toEqual([claim]);
	});

	it('rejects evidence that matches only part of a word', () => {
		const claim = life('ears');
		expect(auditClaims([claim], context).unsupported).toEqual([claim]);
	});

	it('rejects evidence stitched across two records', () => {
		const claim = life('forty years My name was');
		expect(auditClaims([claim], context).unsupported).toEqual([claim]);
	});

	it('leaves atmosphere out of the audit', () => {
		const result = auditClaims(
			[{ claim: 'the night is cold', kind: 'atmosphere', evidence: null }],
			context
		);
		expect(result).toEqual({ life: [], unsupported: [] });
	});
});

// Live eval: tells a story for every recorded case on the real model and judges it. Page fetches
// replay fixtures/stories.json, so only the model calls are live. Run with `pnpm eval`.
import { readFileSync } from 'node:fs';
import { afterAll, describe, expect, it, vi } from 'vitest';
import { epitaph } from '../../src/lib/epitaph.ts';
import { runStoneStory, runStory } from '../../src/lib/server/story.ts';
import type { Candidate, Inscription } from '../../src/lib/types.ts';
import { lifeClaimsScorer } from './life-claims.ts';

interface StoryCase {
	file: string;
	inscription: Inscription;
	candidates: Candidate[];
	pages: Record<string, string | null>;
	match: number | null;
	reviewed: boolean;
}

const { cases, env } = vi.hoisted(() => {
	process.loadEnvFile('.env');
	return {
		cases: JSON.parse(readFileSync('fixtures/stories.json', 'utf8')) as StoryCase[],
		env: { GEMINI_API_KEY: process.env.GEMINI_API_KEY }
	};
});
vi.mock('$app/env/private', () => env);
vi.mock('../../src/lib/server/pages.ts', () => ({
	fetchPage: async (url: string) => cases.flatMap((c) => c.pages[url] ?? [])[0] ?? null
}));

const scorer = lifeClaimsScorer(env.GEMINI_API_KEY ?? '');
const timings: number[] = [];

/**
 * Picks the candidate the story is told about: the labeled match, else the top hit.
 * @param c Recorded case.
 * @returns The candidate, or undefined when research found none or none is the person.
 */
function told(c: StoryCase): Candidate | undefined {
	return c.match === -1 ? undefined : c.candidates[c.match ?? 0];
}

describe('story', () => {
	it.each(cases.map((c) => [c.inscription.name, c] as const))(
		'%s: every life claim is in the records',
		async (_, c) => {
			const candidate = told(c);
			const t0 = performance.now();
			const story = candidate
				? await runStory(c.inscription, candidate)
				: await runStoneStory(c.inscription);
			timings.push(performance.now() - t0);

			expect(story.paragraph, 'the story must always be told').toBeTruthy();
			const stone = epitaph(c.inscription, new Date());
			const records =
				story.status === 'told'
					? story.sources.map((s) => c.pages[s.url] ?? s.snippet)
					: [];
			const result = await scorer.run({
				input: { subject: c.inscription.name, context: [...stone, ...records] },
				output: story.paragraph ?? ''
			});
			expect(result.score, `${story.paragraph}\n\n${result.reason}`).toBe(1);
		},
		180_000
	);
});

afterAll(() => {
	const s = [...timings].sort((a, b) => a - b);
	console.log(`story median ${Math.round(s[Math.floor(s.length / 2)] ?? 0)} ms over ${s.length}`);
});

