import type { Inscription } from '../../src/lib/types.ts';

/**
 * Reads the whole year out of a stone date.
 * @param date Partial date as normalized, e.g. `1943-07-11`, `1943` or `19?3`.
 * @returns The year, or null when absent or not fully legible.
 */
function year(date: string | null): number | null {
	const y = date?.slice(0, 4) ?? '';
	return /^\d{4}$/.test(y) ? Number(y) : null;
}

/**
 * Finds years in a story that fall outside the life the stone records. The stone is the one source
 * known to be about this person, so a year before birth or after death means the records describe
 * someone else.
 * @param paragraph The story as told.
 * @param inscription The stone's person.
 * @returns Offending years, in order of appearance.
 */
export function yearsOutsideLife(paragraph: string, inscription: Inscription): number[] {
	const born = year(inscription.born) ?? -Infinity;
	const died = year(inscription.died) ?? Infinity;
	return [...paragraph.matchAll(/\b\d{4}\b/g)]
		.map((m) => Number(m[0]))
		.filter((y) => y < born || y > died);
}

import { describe, expect, it } from 'vitest';
import type { Inscription } from '../../src/lib/types.ts';
import { yearsOutsideLife } from './stone-years';

/**
 * Builds a stone's person.
 * @param born Birth date as carved.
 * @param died Death date as carved.
 * @returns The inscription.
 */
const stone = (born: string | null, died: string | null): Inscription => ({
	carvedName: 'LLOYD DEE DIXON',
	name: 'Lloyd Dee Dixon',
	maidenName: null,
	born,
	died,
	voice: 'male'
});

describe('yearsOutsideLife', () => {
	it('flags a namesake birth and death that contradict the stone', () => {
		const story = 'I was born on December 20, 1914. I passed on December 1, 2021.';
		expect(yearsOutsideLife(story, stone('1943-07-11', '2018-05-26'))).toEqual([1914, 2021]);
	});

	it('accepts years from birth to death inclusive', () => {
		const story = 'Born in 1943, I worked from 1965 until I died in 2018.';
		expect(yearsOutsideLife(story, stone('1943-07-11', '2018-05-26'))).toEqual([]);
	});

	it('bounds only the side the stone records', () => {
		expect(yearsOutsideLife('I married in 1740 and died in 1752.', stone(null, '1752'))).toEqual(
			[]
		);
		expect(yearsOutsideLife('Still here in 2031.', stone(null, '1752'))).toEqual([2031]);
	});

	it('ignores a date with an illegible digit', () => {
		expect(yearsOutsideLife('Born in 1914.', stone('19?3', '2018'))).toEqual([]);
	});

	it('ignores numbers that are not four-digit years', () => {
		expect(yearsOutsideLife('I lived at 12825 16th Ave for 21 years.', stone('1943', '2018'))).toEqual(
			[]
		);
	});
});

