import type { Coordinates } from './photo-location.ts';

const ENDPOINT = 'https://nominatim.openstreetmap.org/reverse';
// Nominatim's usage policy requires a User-Agent that identifies the application.
const USER_AGENT = 'Gravespeaker (+https://github.com/anchildress1/gravespeaker)';
const TIMEOUT_MS = 5000;
// The usage policy caps clients at one request per second.
const MIN_GAP_MS = 1000;

interface Address {
	city?: string;
	town?: string;
	village?: string;
	hamlet?: string;
	county?: string;
	state?: string;
	country?: string;
}

let nextSlot = 0;

/**
 * Waits for this process's next one-per-second slot.
 */
async function throttle(): Promise<void> {
	const now = Date.now();
	const at = Math.max(now, nextSlot);
	nextSlot = at + MIN_GAP_MS;
	if (at > now) await new Promise((resolve) => setTimeout(resolve, at - now));
}

/**
 * Names the town and state or country at a point, for narrowing search.
 * @param at Where the photo was taken or the visitor stands.
 * @returns For example "Eugene, Oregon", or null when the lookup fails or finds no place.
 */
export async function placeAt(at: Coordinates): Promise<string | null> {
	// Two decimals is about a kilometre: enough for the town, without sending the visitor's spot.
	const params = new URLSearchParams({
		format: 'jsonv2',
		lat: at.lat.toFixed(2),
		lon: at.lon.toFixed(2),
		zoom: '10',
		addressdetails: '1'
	});
	await throttle();
	try {
		const res = await fetch(`${ENDPOINT}?${params}`, {
			headers: { 'user-agent': USER_AGENT, 'accept-language': 'en' },
			signal: AbortSignal.timeout(TIMEOUT_MS)
		});
		if (!res.ok) return null;
		const { address } = (await res.json()) as { address?: Address };
		const local = address?.city ?? address?.town ?? address?.village ?? address?.hamlet ?? address?.county;
		const region = address?.state ?? address?.country;
		return [local, region].filter(Boolean).join(', ') || null;
	} catch {
		// The place only sharpens the search; reading the stone must not fail because of it.
		return null;
	}
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { placeAt } from './geocode';

const eugene = { lat: 44.052099, lon: -123.086754 };
let urls: string[];

/**
 * Stubs the Nominatim boundary.
 * @param respond Builds each response.
 */
const stub = (respond: () => Response | Promise<Response>) => {
	urls = [];
	vi.stubGlobal(
		'fetch',
		vi.fn(async (url: string) => {
			urls.push(url);
			return respond();
		})
	);
};

/**
 * Builds a Nominatim reverse response.
 * @param address Address parts.
 * @returns The response.
 */
const reply = (address: Record<string, string>) => Response.json({ address });

let clock = Date.UTC(2026, 9, 29);
beforeEach(() => {
	vi.useFakeTimers();
	// Each test starts past the previous one's rate-limit slot.
	vi.setSystemTime((clock += 10_000));
});
afterEach(() => {
	vi.useRealTimers();
	vi.unstubAllGlobals();
});

describe('placeAt', () => {
	it('names the town and state', async () => {
		stub(() => reply({ city: 'Eugene', county: 'Lane County', state: 'Oregon' }));
		expect(await placeAt(eugene)).toBe('Eugene, Oregon');
	});

	it.each([
		[{ town: 'Lolo', state: 'Montana' }, 'Lolo, Montana'],
		[{ village: 'Ashby', state: 'Massachusetts' }, 'Ashby, Massachusetts'],
		[{ county: 'Lane County', state: 'Oregon' }, 'Lane County, Oregon'],
		[{ town: 'Westport', country: 'Ireland' }, 'Westport, Ireland'],
		[{ state: 'Oregon' }, 'Oregon']
	])('builds the place from %o', async (address, place) => {
		stub(() => reply(address));
		expect(await placeAt(eugene)).toBe(place);
	});

	it('sends coordinates rounded to about a kilometre', async () => {
		stub(() => reply({ city: 'Eugene', state: 'Oregon' }));
		await placeAt(eugene);
		const params = new URL(urls[0]).searchParams;
		expect([params.get('lat'), params.get('lon')]).toEqual(['44.05', '-123.09']);
	});

	it.each([
		['an HTTP error', () => new Response('busy', { status: 429 })],
		['no address', () => Response.json({ error: 'Unable to geocode' })],
		[
			'a network failure',
			() => {
				throw new TypeError('fetch failed');
			}
		]
	])('returns null on %s', async (_, respond) => {
		stub(respond);
		expect(await placeAt(eugene)).toBeNull();
	});

	it('waits a second between lookups', async () => {
		stub(() => reply({ city: 'Eugene', state: 'Oregon' }));
		await placeAt(eugene);
		const second = placeAt(eugene);
		await vi.advanceTimersByTimeAsync(999);
		expect(urls).toHaveLength(1);
		await vi.advanceTimersByTimeAsync(1);
		expect(await second).toBe('Eugene, Oregon');
		expect(urls).toHaveLength(2);
	});
});

