	const lon = form.get('lon');
	if (lat === null && lon === null) return null;
	const point = { lat: Number(lat), lon: Number(lon) };
	const valid =
		typeof lat === 'string' &&
		typeof lon === 'string' &&
		lat.trim() !== '' &&
		lon.trim() !== '' &&
		Math.abs(point.lat) <= 90 &&
		Math.abs(point.lon) <= 180;
	return valid ? point : undefined;
}

